SELECT id, company_name, company_logo, contact_name, contact_phone,
       company_address, business_license, status, email_suffix, created_at, updated_at
FROM enterprises WHERE id = #{id}

SELECT id, company_name, company_logo, contact_name, contact_phone,
       company_address, business_license, status, email_suffix, created_at, updated_at
FROM enterprises WHERE email_suffix = #{emailSuffix}
